import{_ as a,c as s,o as t,ag as e}from"./chunks/framework.DPDPlp3K.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"wechat/old/Git高手必看！合并提交历史技巧.wechat.md","filePath":"wechat/old/Git高手必看！合并提交历史技巧.wechat.md"}'),l={name:"wechat/old/Git高手必看！合并提交历史技巧.wechat.md"};function h(n,i,p,c,o,d){return t(),s("div",null,i[0]||(i[0]=[e('<h2 id="标题备选" tabindex="-1">标题备选 <a class="header-anchor" href="#标题备选" aria-label="Permalink to &quot;标题备选&quot;">​</a></h2><ol><li>Git 进阶实战：Git高手必看！合并提交历史技巧🔧</li><li>别再手动重复操作了！这篇讲清楚 Git高手必看！合并提交历史技巧🔧</li><li>手把手教你：用 Git高手必看！合并提交历史技巧🔧 提升开发效率</li></ol><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>这篇文章适合想提升 Git 工作流效率的同学，围绕「Git高手必看！合并提交历史技巧🔧」梳理实用操作、使用场景和注意事项，让提交管理更清晰。</p><h2 id="正文" tabindex="-1">正文 <a class="header-anchor" href="#正文" aria-label="Permalink to &quot;正文&quot;">​</a></h2><p>哈喽大家好👋 我是程序🦍kk。把复杂知识掰成大白话讲明白，是我一直以来的小追求✨；<strong>打好基础才能稳步进阶</strong>，是我始终秉持的学习理念～</p><blockquote><p>📢 我搭建了5000人程序猿专属学习交流群 群内会同步前端开发/全栈开发/Web3开发/远程工作等干货资源 关注我并回复 <strong>加群</strong> ，就能加入交流圈啦🚀</p></blockquote><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p><strong>Git 用得顺不顺，很多时候差别就在这些进阶操作里。</strong></p><p>日常开发里，提交历史、自动化钩子、协作流程这些东西看起来不起眼，但一旦项目变大，就会直接影响代码管理效率。</p><p>这篇文章会把「Git高手必看！合并提交历史技巧🔧」整理成一份更清晰的实战笔记，方便大家按场景选择合适的 Git 操作方式。</p><h2 id="核心操作整理" tabindex="-1">核心操作整理 <a class="header-anchor" href="#核心操作整理" aria-label="Permalink to &quot;核心操作整理&quot;">​</a></h2><p>下面按原文内容继续展开。建议大家先在测试仓库里验证命令，再放到正式项目里使用。</p><p>如果你准备把这些 Git 操作用到团队项目里，建议先约定好提交规范和分支策略，再统一落地。</p><p>在Git中，合并提交历史可以针对本地仓库或远程仓库进行。以下是几种常见的场景和相关命令，并说明了如何处理远程仓库的情况：</p><h2 id="_1-使用-git-rebase-i-交互式变基" tabindex="-1">1. 使用 <code>git rebase -i</code> 交互式变基 <a class="header-anchor" href="#_1-使用-git-rebase-i-交互式变基" aria-label="Permalink to &quot;1. 使用 `git rebase -i` 交互式变基&quot;">​</a></h2><p>这种方法主要用于合并本地的提交历史。如果需要更新远程仓库，则需要使用强制推送。</p><h3 id="本地操作" tabindex="-1">本地操作： <a class="header-anchor" href="#本地操作" aria-label="Permalink to &quot;本地操作：&quot;">​</a></h3><ol><li><p>查看提交历史：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> log</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --oneline</span></span></code></pre></div></li><li><p>启动交互式变基：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> rebase</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -i</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> HEAD~N</span></span></code></pre></div></li><li><p>编辑提交记录，将要合并的提交前缀改为 <code>squash</code> 或 <code>fixup</code>。</p></li><li><p>保存并退出编辑器。</p></li></ol><h3 id="远程操作" tabindex="-1">远程操作： <a class="header-anchor" href="#远程操作" aria-label="Permalink to &quot;远程操作：&quot;">​</a></h3><p>如果你修改了已经推送到远程的提交历史，需要使用强制推送：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> push</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --force</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> origin</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> branch-name</span></span></code></pre></div><p>注意：强制推送可能会覆盖远程仓库的历史，请谨慎使用。</p><h2 id="_2-使用-git-merge-squash" tabindex="-1">2. 使用 <code>git merge --squash</code> <a class="header-anchor" href="#_2-使用-git-merge-squash" aria-label="Permalink to &quot;2. 使用 `git merge --squash`&quot;">​</a></h2><p>这种方法可以用于合并本地分支的提交，也可以用于合并远程分支的提交。</p><h3 id="本地操作-1" tabindex="-1">本地操作： <a class="header-anchor" href="#本地操作-1" aria-label="Permalink to &quot;本地操作：&quot;">​</a></h3><ol><li><p>切换到目标分支：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> checkout</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> main</span></span></code></pre></div></li><li><p>合并其他分支的提交：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> merge</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --squash</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> feature-branch</span></span></code></pre></div></li><li><p>提交更改：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> commit</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -m</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> &quot;Squashed commit&quot;</span></span></code></pre></div></li></ol><h3 id="远程操作-1" tabindex="-1">远程操作： <a class="header-anchor" href="#远程操作-1" aria-label="Permalink to &quot;远程操作：&quot;">​</a></h3><p>如果 <code>feature-branch</code> 是远程分支，先拉取然后再合并：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> fetch</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> origin</span></span>\n<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> merge</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --squash</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> origin/feature-branch</span></span>\n<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> commit</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -m</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> &quot;Squashed remote branch&quot;</span></span>\n<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> push</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> origin</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> main</span></span></code></pre></div><h2 id="_3-使用-git-reset-soft-合并最后的几次提交" tabindex="-1">3. 使用 <code>git reset --soft</code> 合并最后的几次提交 <a class="header-anchor" href="#_3-使用-git-reset-soft-合并最后的几次提交" aria-label="Permalink to &quot;3. 使用 `git reset --soft` 合并最后的几次提交&quot;">​</a></h2><p>这种方法主要用于合并本地的最近几次提交。如果这些提交已经推送到远程，则需要强制推送。</p><h3 id="本地操作-2" tabindex="-1">本地操作： <a class="header-anchor" href="#本地操作-2" aria-label="Permalink to &quot;本地操作：&quot;">​</a></h3><ol><li><p>查看提交历史：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> log</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --oneline</span></span></code></pre></div></li><li><p>回退到某个提交：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> reset</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --soft</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> HEAD~N</span></span></code></pre></div></li><li><p>提交更改：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> commit</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -m</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> &quot;Merged commits&quot;</span></span></code></pre></div></li></ol><h3 id="远程操作-2" tabindex="-1">远程操作： <a class="header-anchor" href="#远程操作-2" aria-label="Permalink to &quot;远程操作：&quot;">​</a></h3><p>如果你修改了已推送的提交历史，需要强制推送：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> push</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --force</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> origin</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> branch-name</span></span></code></pre></div><h2 id="_4-使用-git-commit-amend-修改最近的提交" tabindex="-1">4. 使用 <code>git commit --amend</code> 修改最近的提交 <a class="header-anchor" href="#_4-使用-git-commit-amend-修改最近的提交" aria-label="Permalink to &quot;4. 使用 `git commit --amend` 修改最近的提交&quot;">​</a></h2><p>这种方法用于修改本地最近的提交。如果该提交已推送到远程，则需要强制推送。</p><h3 id="本地操作-3" tabindex="-1">本地操作： <a class="header-anchor" href="#本地操作-3" aria-label="Permalink to &quot;本地操作：&quot;">​</a></h3><ol><li><p>添加更改：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> add</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> .</span></span></code></pre></div></li><li><p>修改上一个提交：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> commit</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --amend</span></span></code></pre></div></li></ol><h3 id="远程操作-3" tabindex="-1">远程操作： <a class="header-anchor" href="#远程操作-3" aria-label="Permalink to &quot;远程操作：&quot;">​</a></h3><p>如果你修改了已推送的提交，需要强制推送：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">git</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> push</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --force</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> origin</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> branch-name</span></span></code></pre></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><ul><li>所有这些方法主要用于合并本地的提交历史。</li><li>如果你修改了已经推送到远程的提交历史，需要使用 <code>git push --force</code> 来更新远程仓库。</li><li>强制推送可能会导致协作者的工作出现问题，因此在共享分支上使用时要特别小心。</li><li>在使用这些命令前，建议先备份你的工作分支。</li><li>对于团队协作的项目，最好在进行这些操作前与团队成员沟通.</li><li><strong><code>git rebase -i</code></strong>：适合在提交历史中选择性地合并多个提交。</li><li><strong><code>git merge --squash</code></strong>：适合在合并分支时将整个分支的提交合并为一个提交。</li><li><strong><code>git reset --soft</code></strong>：适合将最近的几个提交合并为一个提交。</li><li><strong><code>git commit --amend</code></strong>：适合修改或合并最近的提交。</li></ul><p>选择适合你的需求的方法，确保在使用这些命令前备份好工作分支，因为历史修改可能会导致提交丢失。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>好啦，今天的分享就到这里！</p><p>💬 互动时间：</p><p>你平时最常用的 Git 进阶操作是哪一个？如果你想看「提交规范 / 分支模型 / Hooks 自动化」的后续实战，也可以直接留言。</p><p>最后，感谢你看到这里👏</p><p>如果喜欢这篇内容，不妨顺手给小编安排一波👇 <strong>点赞</strong>👍｜<strong>转发</strong>📲｜<strong>推荐</strong>❤️｜<strong>评论</strong>📣</p><p>要是想第一时间蹲到新内容推送，记得给我点个<strong>星标</strong>⭐️</p><p>更多干货内容正在持续填坑中，咱们下期见👋</p><h2 id="标签建议" tabindex="-1">标签建议 <a class="header-anchor" href="#标签建议" aria-label="Permalink to &quot;标签建议&quot;">​</a></h2><p>category:、编程相关、Git、开发效率、工程化</p>',57)]))}const g=a(l,[["render",h]]);export{r as __pageData,g as default};
